      "slo_id": "S6",
      "level": "understand",
      "question": "Which of these is the correct way to rewrite $a^{-n}$?",
      "options": [
        "$\\frac{1}{a^n}$",
        "$-a^n$",
        "$a^n$"
      ],
      "correct_index": 0,
      "explanation": "A negative exponent indicates the reciprocal of the base raised to the positive exponent.",
      "selected_because": "Rule for negative exponents from the lesson.",
      "distractor_misconceptions": {
        "1": "Confuses negative exponent with negative base.",
        "2": "Ignores the negative sign in the exponent."
      },
      "option_feedback": {
        "correct": "That's right! A negative exponent means to take the reciprocal of the base with a positive exponent.",
        "wrong": {
          "1": "A negative exponent does not make the base negative. It means to take the reciprocal. Remember, $5^{-2}$ is not $-25$, it is $\\frac{1}{5^2}$.",
          "2": "A negative exponent doesn't just disappear. It tells you to find the reciprocal of the base raised to the positive exponent. For example, $10^{-1}$ is $\\frac{1}{10^1}$."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Rewrite $a^{-n}$ as $\\frac{1}{a^n}$ and simplify.",
      "teaching_error": null
    }
  ]
